begin read only;
set local statement_timeout = '5s';
set local lock_timeout = '1s';
with target as (select c.oid,c.relname,c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('orders','components','inventory','assemblies','assembly_bom','admin_members')), columns as (select t.relname,jsonb_agg(jsonb_build_object('column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',not a.attnotnull) order by a.attnum) as cols from target t join pg_attribute a on a.attrelid=t.oid where a.attnum>0 and not a.attisdropped and ((t.relname='orders' and a.attname in ('id','items','sales_channel','external_reference','order_date','subtotal_pence','delivery_pence','total_pence','payment_status','refunded_pence','updated_at')) or (t.relname='components' and a.attname in ('id','internal_unit_cost','stock_unit')) or t.relname in ('inventory','assembly_bom','admin_members') or (t.relname='assemblies' and a.attname in ('id','kind'))) group by t.relname), report as (select jsonb_build_object('columns',(select jsonb_object_agg(relname,cols) from columns),'tables',(select jsonb_agg(jsonb_build_object('table',relname,'rls',relrowsecurity,'authenticated_select',has_table_privilege('authenticated',oid,'SELECT'))) from target),'policies',(select jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'command',cmd,'roles',roles,'using',qual,'check',with_check)) from pg_policies where schemaname='public' and tablename in ('orders','components','inventory','assemblies','assembly_bom','admin_members')),'functions',(select jsonb_agg(jsonb_build_object('name',proname,'arguments',pg_get_function_identity_arguments(oid),'definer',prosecdef,'bodyMD5',md5(prosrc),'settings',proconfig)) from pg_proc where pronamespace='public'::regnamespace and proname in ('create_external_order','edit_external_order','apply_order_inventory')),'costingObjects',(select coalesce(jsonb_agg(c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','v') and c.relname ~ '(acquisition|financial|cost_batch|cost_movement|marketplace_fee|profit)')) as value) select case when octet_length(value::text)<=8192 then value else jsonb_build_object('rejected','metadata byte ceiling','bytes',octet_length(value::text)) end as metadata from report limit 1;
commit;
